    // Compute the SVD of the centered points matrix. The normal is the right singular vector
    // corresponding to the smallest singular value.
    // But we can approximate by building the 3x3 matrix A^T A and finding its eigenvector.

    // Build the symmetric matrix
    double A[3][3] = {{cxx, cxy, cxz}, {cxy, cyy, cyz}, {cxz, cyz, czz}};

