    double V[3][3] = {{1,0,0}, {0,1,0}, {0,0,1}}; // eigenvectors
    double B[3][3];
    for (int i=0; i<3; i++) for (int j=0; j<3; j++) B[i][j] = A[i][j];

    for (int iter=0; iter<50; iter++) {
