    if (B[2][2] < min_eval) { min_eval = B[2][2]; min_idx = 2; }

    // The eigenvector for smallest eigenvalue is column min_idx of V
    double nx = V[0][min_idx];
    double ny = V[1][min_idx];
    double nz = V[2][min_idx];

