    }
    nx /= norm; ny /= norm; nz /= norm;

    // Ensure consistent orientation (optional)
    // Compute d = -n·centroid
    double d = -(nx * centroid.x() + ny * centroid.y() + nz * centroid.z());

    return Kernel::Plane_3(nx, ny, nz, d);
